import { ValidationError } from './errors';

export const taskStatuses = ['todo', 'in progress', 'done'] as const;
export type TaskStatus = (typeof taskStatuses)[number];

export function asTaskStatus(value: string): TaskStatus {
  if ((taskStatuses as readonly string[]).includes(value)) {
    return value as TaskStatus;
  }
  throw new ValidationError('Status must be todo, in progress, or done');
}

